#pragma once
#include <cstdint>

// Generated by scripts/convert_mono_image.py from highlight.png.
namespace pulp_highlight {

constexpr int kWidth = 8;
constexpr int kHeight = 8;
constexpr int kRowBytes = 1;

// Row-major, MSB first; 1 = white, 0 = black.
static const uint8_t kPixels[] = {
    0x55, 0xFF, 0x55, 0xFF, 0x55, 0xFF, 0x55, 0xFF,
};

inline bool isBlack(const int x, const int y) {
  return !(kPixels[y * kRowBytes + (x >> 3)] & (0x80 >> (x & 7)));
}

}  // namespace pulp_highlight
